#!/bin/sh
# Assemble the static files Workers serves: the web module's files plus
# /theme.css, generated by the same function the API serves it from.
set -eu
here=$(cd "$(dirname "$0")" && pwd)
repo=$(cd "$here/../.." && pwd)

rm -rf "$here/dist"
cp -R "$repo/modules/web/static" "$here/dist"
(cd "$repo" && uv run --no-sync python -c \
  'import sys; from kundli_api.serialize import theme_css; sys.stdout.write(theme_css())') \
  > "$here/dist/theme.css"
echo "assets: $(find "$here/dist" -type f | wc -l) files in $here/dist"
